(()=>{const origin='https://www.quadralevel.com';window.QLLearning={request:(action,chapter,extra={})=>new Promise((resolve,reject)=>{if(parent===window){reject(new Error('افتح التقييم من صفحة الفصل داخل المنصة.'));return}const requestId='ql-'+Date.now()+'-'+Math.random().toString(36).slice(2);const timer=setTimeout(()=>{removeEventListener('message',receive);reject(new Error('انتهت مهلة الاتصال. أعد المحاولة.'))},120000);function receive(e){const d=e.data||{};if(e.source!==parent||e.origin!==origin||d.type!=='ql-learning-response'||d.requestId!==requestId)return;clearTimeout(timer);removeEventListener('message',receive);d.ok?resolve(d.payload):reject(new Error(d.payload?.error||'تعذر الاتصال'))}addEventListener('message',receive);parent.postMessage({type:'ql-learning-request',requestId,action,chapter,...extra},origin)})};})();